    required this.publishedAtMs,
    required this.durationMs,
    required this.viewCount,
    this.thumbnailUrl,
    this.isSubOnly,
    this.expiresAtMs,
    this.positionMs,
    this.progressUpdatedAtMs,
    required this.watched,
    required this.savedFiles,
  });

  @override
  int get hashCode =>
      videoId.hashCode ^
      userId.hashCode ^
      userLogin.hashCode ^
      userName.hashCode ^
      videoType.hashCode ^
      title.hashCode ^
      publishedAtMs.hashCode ^
      durationMs.hashCode ^
      viewCount.hashCode ^
      thumbnailUrl.hashCode ^
      isSubOnly.hashCode ^
      expiresAtMs.hashCode ^
      positionMs.hashCode ^
      progressUpdatedAtMs.hashCode ^
      watched.hashCode ^
      savedFiles.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CoreTwitchVideo &&
          runtimeType == other.runtimeType &&
          videoId == other.videoId &&
          userId == other.userId &&
          userLogin == other.userLogin &&
          userName == other.userName &&
          videoType == other.videoType &&
          title == other.title &&
          publishedAtMs == other.publishedAtMs &&
          durationMs == other.durationMs &&
          viewCount == other.viewCount &&
          thumbnailUrl == other.thumbnailUrl &&
          isSubOnly == other.isSubOnly &&
          expiresAtMs == other.expiresAtMs &&
          positionMs == other.positionMs &&
          progressUpdatedAtMs == other.progressUpdatedAtMs &&
          watched == other.watched &&
          savedFiles == other.savedFiles;
}

/// Error of a Twitch call (no tokens in the message).
class TwitchApiError implements FrbException {
  final TwitchErrorKind kind;

  /// `kind` as a stable code (CORE-009): `not_configured`, `signed_out`,
  /// `reauth_required`, `login_denied`, `login_expired`, `network`,
  /// `rate_limited`, `twitch`, `database`, `invalid`, `restricted`.
  final String code;
  final String message;

  const TwitchApiError({
    required this.kind,
    required this.code,
    required this.message,
  });

  @override
  int get hashCode => kind.hashCode ^ code.hashCode ^ message.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TwitchApiError &&
          runtimeType == other.runtimeType &&
          kind == other.kind &&
          code == other.code &&
          message == other.message;
}

/// What went wrong; Dart receives it as an exception.
enum TwitchErrorKind {
  /// No Twitch client id in this build: only local data.
  notConfigured,

  /// The call needs a Twitch sign-in.
  signedOut,

  /// The sign-in expired: sign in again.
  reauthRequired,

  /// The user declined on twitch.tv/activate.
  loginDenied,

  /// The sign-in code expired before it was confirmed.
  loginExpired,

  /// No network or Twitch unreachable.
  network,

  /// Twitch rate limit; try later.
  rateLimited,

  /// Twitch answered with an error.
  twitch,

  /// The local database failed.
  storage,

  /// Bad argument (not a Twitch id, empty query).
  invalid,

  /// The active profile is a kid or restricted profile: no Twitch
  /// notifications for it (TWI-009, UI-015).
  restricted,
}
